3	namespace App\Jobs\Stripe;
4	
5	use App\Models\Core\Professional\Professional;
6	use App\Services\Professional\BrandPartnerLinkAuditor;
7	use App\Services\Professional\BrandPartnerLinkNotifier;
8	use App\Services\Stripe\CommissionVoidService;
9	use Illuminate\Bus\Queueable;
10	use Illuminate\Contracts\Queue\ShouldQueue;
11	use Illuminate\Foundation\Bus\Dispatchable;
12	use Illuminate\Queue\InteractsWithQueue;
13	use Illuminate\Queue\SerializesModels;
14	use Illuminate\Support\Facades\Log;
15	
16	// Voids all pending commission entries for a disconnected brand-affiliate
17	// pair when the count exceeds the sync cap (200). Dispatched after
18	// BrandPartnerLinkLifecycleService commits the disconnect transaction.
19	//
20	// Idempotent — voidEntry() uses optimistic locking, so retries are safe.
21	class VoidPendingCommissionsForLinkJob implements ShouldQueue
22	{
23	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
24	
25	    public int $tries = 3;
26	
27	    public int $backoff = 60;
28	
29	    public function __construct(
30	        public readonly string $affiliateProfessionalId,
31	        public readonly string $brandProfessionalId,
32	        public readonly string $reason,
33	    ) {
34	        $this->onQueue('stripe');
35	    }
36	
37	    public function handle(
38	        CommissionVoidService $voidService,
39	        BrandPartnerLinkAuditor $auditor,
40	        BrandPartnerLinkNotifier $notifier,
41	    ): void {
42	        [$affiliate, $brand] = $this->loadProfessionals();
43	
44	        if (! $affiliate || ! $brand) {
45	            Log::warning('VoidPendingCommissionsForLinkJob: missing professional, skipping.', [
46	                'affiliate_id' => $this->affiliateProfessionalId,
47	                'brand_id' => $this->brandProfessionalId,
48	            ]);
49	
50	            return;
51	        }
52	
53	        $result = $voidService->runVoidLoop(
54	            $this->affiliateProfessionalId,
55	            $this->brandProfessionalId,
56	            $this->reason,
57	        );
58	
59	        $auditor->recordAsyncVoidCompletion(
60	            $this->brandProfessionalId,
61	            $this->affiliateProfessionalId,
62	            $result['count'],
63	            $result['total_cents'],
64	            $this->reason,
65	        );
66	
67	        $notifier->notifyAffiliateOfRemoval($affiliate, $brand, $result['total_cents']);
68	        $notifier->notifyBrandOfRemoval($brand, $affiliate);
69	    }
70	
71	    /** @return array{0: ?Professional, 1: ?Professional} */
72	    public function loadProfessionals(): array
73	    {
74	        return [
75	            Professional::find($this->affiliateProfessionalId),
76	            Professional::find($this->brandProfessionalId),
77	        ];
78	    }
79	}
80

