3	namespace App\Jobs\Shopify;
4	
5	use App\Models\Commerce\Order;
6	use App\Models\Commerce\OrderEvent;
7	use App\Models\Core\Professional\BrandPartnerLink;
8	use App\Models\Core\Professional\Professional;
9	use App\Models\Core\Professional\ProfessionalIntegration;
10	use App\Models\Retail\BrandStoreSettings;
11	use App\Services\Cache\AnalyticsCacheService;
12	use App\Services\Customers\ContactCaptureService;
13	use App\Services\Store\BrandCatalogService;
14	use Illuminate\Bus\Queueable;
15	use Illuminate\Contracts\Queue\ShouldQueue;
16	use Illuminate\Database\UniqueConstraintViolationException;
17	use Illuminate\Foundation\Bus\Dispatchable;
18	use Illuminate\Queue\InteractsWithQueue;
19	use Illuminate\Queue\SerializesModels;
20	use Illuminate\Support\Arr;
21	use Illuminate\Support\Facades\DB;
22	use Illuminate\Support\Facades\Log;
23	
24	// Phase 3: Processes orders/paid webhooks. Writes commerce.orders (LWW upsert) +
25	// commerce.order_events (idempotent via shopify_event_id). Triggers maintain
26	// order_items and brand_affiliate_rollup automatically.
27	class ProcessShopifyOrderWebhookJob implements ShouldQueue
28	{
29	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
30	
31	    public int $tries = 3;
32	
33	    public int $timeout = 30;
34	
35	    public function __construct(
36	        public string $brandProfessionalId,
37	        public array $orderPayload,
38	        public string $shopifyEventId = '',
39	        // 'webhook' for live webhook deliveries; 'reconciler' for backstop-sourced events.
40	        public string $source = 'webhook',
41	    ) {
42	        $this->onQueue('integrations');
43	    }
44	
45	    public function handle(
46	        ContactCaptureService $contactCapture,
47	        BrandCatalogService $catalogService,
48	        AnalyticsCacheService $analyticsCache,
49	    ): void {
50	        $start = microtime(true);
51	
52	        $this->process($contactCapture, $catalogService, $analyticsCache);
53	
54	        // Alert threshold: 15s = 50% of job timeout. Slow path here usually means
55	        // the BrandCatalogService metafield fetch or the LWW upsert is degraded.
56	        // Configure a Nightwatch alert on this warning to catch trouble before
57	        // the 30s timeout starts failing webhook deliveries.
58	        $durationMs = (int) round((microtime(true) - $start) * 1000);
59	        if ($durationMs > 15_000) {
60	            Log::warning('ProcessShopifyOrderWebhookJob slow processing', [
61	                'order_id' => (string) Arr::get($this->orderPayload, 'id', ''),
62	                'brand_professional_id' => $this->brandProfessionalId,
63	                'duration_ms' => $durationMs,
64	                'attempt' => $this->attempts(),
65	            ]);
66	        }
67	    }
68	
69	    private function process(
70	        ContactCaptureService $contactCapture,
71	        BrandCatalogService $catalogService,
72	        AnalyticsCacheService $analyticsCache,
73	    ): void {
74	        $orderId = (string) Arr::get($this->orderPayload, 'id', '');
75	        $shopDomain = strtolower(trim((string) Arr::get($this->orderPayload, 'domain', '')));
76	        $noteAttributes = Arr::get($this->orderPayload, 'note_attributes', []);
77	        $lineItems = Arr::get($this->orderPayload, 'line_items', []);
78	        $currency = strtoupper(trim((string) Arr::get($this->orderPayload, 'currency', 'AUD')));
79	        $occurredAt = Arr::get($this->orderPayload, 'created_at', now()->toIso8601String());
80	        $shopifyUpdatedAt = Arr::get($this->orderPayload, 'updated_at', $occurredAt);
81	
82	        if ($orderId === '') {
83	            Log::warning('ProcessShopifyOrderWebhookJob: missing order id, skipping', [
84	                'brand_professional_id' => $this->brandProfessionalId,
85	            ]);
86	
87	            return;
88	        }
89	
90	        // Resolve affiliate from note_attributes. Preserves the same extraction
91	        // logic as the previous job — the cart attribute key is 'affiliate'.
92	        $affiliateSlug = $this->extractCartAttribute($noteAttributes, 'affiliate');
93	
94	        if ($affiliateSlug === '') {
95	            Log::info('ProcessShopifyOrderWebhookJob: no affiliate attribute, skipping', [
96	                'order_id' => $orderId,
97	                'brand_professional_id' => $this->brandProfessionalId,
98	            ]);
99	
100	            return;
101	        }
102	
103	        $affiliate = Professional::query()
104	            ->where('handle_lc', strtolower($affiliateSlug))
105	            ->first();
106	
107	        if (! $affiliate) {
108	            Log::warning('ProcessShopifyOrderWebhookJob: affiliate not found', [
109	                'order_id' => $orderId,
110	                'affiliate_slug' => $affiliateSlug,
111	            ]);
112	
113	            return;
114	        }
115	
116	        // Verify affiliate is connected to this brand before writing any commerce rows.
117	        $isConnected = BrandPartnerLink::query()
118	            ->where('affiliate_professional_id', $affiliate->id)
119	            ->where('brand_professional_id', $this->brandProfessionalId)
120	            ->exists();
121	
122	        if (! $isConnected) {
123	            Log::warning('ProcessShopifyOrderWebhookJob: affiliate not connected to brand', [
124	                'order_id' => $orderId,
125	                'affiliate_id' => (string) $affiliate->id,
126	                'brand_professional_id' => $this->brandProfessionalId,
127	            ]);
128	
129	            return;
130	        }
131	
132	        // Resolve integration for currency validation and metafield overrides.
133	        $integration = ProfessionalIntegration::query()
134	            ->where('professional_id', $this->brandProfessionalId)
135	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
136	            ->first();
137	
138	        // Currency mismatch guard: commission math would be wrong unit on multi-currency misconfiguration.
139	        $shopCurrency = strtoupper(trim((string) Arr::get($integration?->provider_metadata ?? [], 'shop_currency', '')));
140	        if ($shopCurrency !== '' && $shopCurrency !== $currency) {
141	            Log::warning('ProcessShopifyOrderWebhookJob: currency mismatch, skipping', [
142	                'order_id' => $orderId,
143	                'brand_professional_id' => $this->brandProfessionalId,
144	                'order_currency' => $currency,
145	                'shop_currency' => $shopCurrency,
146	            ]);
147	
148	            return;
149	        }
150	
151	        // Use shop_domain from the integration record (authoritative); fall back to payload.
152	        $shopDomain = $integration?->shopify_shop_domain ?? $shopDomain;
153	
154	        $brandSettings = BrandStoreSettings::where('professional_id', $this->brandProfessionalId)->first();
155	        $platformDefault = (float) config('partna.store.default_commission_rate', 15);
156	
157	        // Collect GIDs for a single-call metafield override fetch.
158	        $productGids = $this->extractProductGids($lineItems);
159	        $overrideMap = ($integration && ! empty($productGids))
160	            ? $catalogService->fetchCommissionOverridesForProducts($integration, $productGids)
161	            : [];
162	
163	        // Pre-compute per-line commission and serialize into line_items JSONB.
164	        // Postgres triggers can't access PHP business logic (metafields, brand defaults),
165	        // so commission is resolved here and stored in the JSONB for the trigger to read.
166	        [$enrichedLineItems, $totalGrossCents, $totalDiscountCents, $totalCommissionCents, $commissionRate, $rateSource] =
167	            $this->buildEnrichedLineItems($lineItems, $overrideMap, $brandSettings, $platformDefault, $currency, $orderId);
168	
169	        // Strip GDPR-tracked PII to a safe shopify_data snapshot before writing.
170	        // Per ADR 0001, full redaction happens in RedactCustomerJob; here we store
171	        // only the non-PII structural fields needed for reconciliation.
172	        $shopifyData = $this->buildSafeShopifyData($this->orderPayload);
173	
174	        // LWW upsert: the WHERE guard is enforced in SQL, not PHP — out-of-order
175	        // delivery with an older shopify_updated_at leaves the existing row untouched.
176	        $this->upsertOrder(
177	            orderId: $orderId,
178	            shopDomain: $shopDomain,
179	            brandProfessionalId: $this->brandProfessionalId,
180	            affiliateProfessionalId: (string) $affiliate->id,
181	            grossCents: $totalGrossCents,
182	            discountCents: $totalDiscountCents,
183	            commissionCents: $totalCommissionCents,
184	            commissionRate: $commissionRate,
185	            rateSource: $rateSource,
186	            currency: $currency,
187	            lineItems: $enrichedLineItems,
188	            shopifyData: $shopifyData,
189	            occurredAt: $occurredAt,
190	            shopifyUpdatedAt: $shopifyUpdatedAt,
191	        );
192	
193	        // Fetch the order id for the event FK after upsert.
194	        $order = Order::query()
195	            ->where('shopify_shop_domain', $shopDomain)
196	            ->where('shopify_order_id', $orderId)
197	            ->first();
198	
199	        if ($order) {
200	            $this->insertOrderEvent(
201	                orderId: (string) $order->id,
202	                eventType: 'paid',
203	                shopifyEventId: $this->shopifyEventId,
204	                source: $this->source,
205	                metadata: [
206	                    'shopify_order_id' => $orderId,
207	                    'financial_status' => Arr::get($this->orderPayload, 'financial_status', ''),
208	                ],
209	                shopifyTriggeredAt: $occurredAt,
210	            );
211	
212	            // Invalidate caches for both brand and affiliate so dashboards reflect this order.
213	            $analyticsCache->invalidateAnalytics($this->brandProfessionalId);
214	            $analyticsCache->invalidateAnalytics((string) $affiliate->id);
215	        }
216	
217	        // Capture the buyer as an affiliate contact — independent of commerce writes.
218	        $this->captureAffiliateContact($contactCapture, (string) $affiliate->id, $noteAttributes, $orderId);
219	
220	        Log::info('ProcessShopifyOrderWebhookJob: processed', [
221	            'order_id' => $orderId,
222	            'brand_professional_id' => $this->brandProfessionalId,
223	            'affiliate_id' => (string) $affiliate->id,
224	            'commission_cents' => $totalCommissionCents,
225	        ]);
226	    }
227	
228	    /**
229	     * INSERT ... ON CONFLICT DO UPDATE WHERE EXCLUDED.shopify_updated_at > orders.shopify_updated_at.
230	     * The LWW guard is entirely in SQL — PHP never compares timestamps.
231	     */
232	    private function upsertOrder(
233	        string $orderId,
234	        string $shopDomain,
235	        string $brandProfessionalId,
