318	    /**
319	     * Build line_items JSONB with pre-computed commission per line.
320	     * Returns [$enrichedItems, $totalGrossCents, $totalDiscountCents, $totalCommissionCents, $rate, $rateSource].
321	     *
322	     * @param  array<int, array<string, mixed>>  $lineItems
323	     * @param  array<string, float|null>  $overrideMap
324	     * @return array{0: list<array<string, mixed>>, 1: int, 2: int, 3: int, 4: float, 5: string}
325	     */
326	    private function buildEnrichedLineItems(
327	        array $lineItems,
328	        array $overrideMap,
329	        ?BrandStoreSettings $brandSettings,
330	        float $platformDefault,
331	        string $currency,
332	        string $orderId,
333	    ): array {
334	        $enriched = [];
335	        $totalGrossCents = 0;
336	        $totalDiscountCents = 0;
337	        $totalCommissionCents = 0;
338	        $resolvedRate = 0.0;
339	        $resolvedRateSource = 'platform_default';
340	
341	        foreach ($lineItems as $lineItem) {
342	            if (! is_array($lineItem)) {
343	                continue;
344	            }
345	
346	            $lineItemId = (string) Arr::get($lineItem, 'id', '');
347	            $unitPrice = (float) Arr::get($lineItem, 'price', 0);
348	            $quantity = (int) Arr::get($lineItem, 'quantity', 1);
349	
350	            if ($lineItemId === '' || $unitPrice <= 0 || $quantity <= 0) {
351	                continue;
352	            }
353	
354	            $productIdStr = (string) Arr::get($lineItem, 'product_id', '');
355	            $productGid = ($productIdStr !== '' && preg_match('/^\d+$/', $productIdStr))
356	                ? "gid://shopify/Product/{$productIdStr}"
357	                : '';
358	
359	            [$rate, $rateSource] = $this->resolveCommissionRate(
360	                $productGid,
361	                $overrideMap,
362	                $brandSettings,
363	                $platformDefault,
364	            );
365	            $resolvedRate = $rate;
366	            $resolvedRateSource = $rateSource;
367	
368	            $linePricePreDiscount = (int) round($unitPrice * $quantity * 100);
369	            $totalDiscountRaw = (float) Arr::get($lineItem, 'total_discount', 0);
370	            $lineDiscountCents = (int) round($totalDiscountRaw * 100);
371	            $lineTotalCents = max(0, $linePricePreDiscount - $lineDiscountCents);
372	
373	            $lineCommissionCents = (int) round($lineTotalCents * ($rate / 100));
374	
375	            $totalGrossCents += $lineTotalCents;
376	            $totalDiscountCents += $lineDiscountCents;
377	            $totalCommissionCents += $lineCommissionCents;
378	
379	            $enriched[] = [
380	                'shopify_line_item_id' => $lineItemId,
381	                'shopify_product_id' => $productIdStr,
382	                'shopify_variant_id' => (string) Arr::get($lineItem, 'variant_id', ''),
383	                'sku' => (string) Arr::get($lineItem, 'sku', ''),
384	                'title' => (string) Arr::get($lineItem, 'title', ''),
385	                'quantity' => $quantity,
386	                'unit_price_cents' => (int) round($unitPrice * 100),
387	                'discount_cents' => $lineDiscountCents,
388	                'line_total_cents' => $lineTotalCents,
389	                'commission_cents' => $lineCommissionCents,
390	                'commission_rate' => $rate,
391	            ];
392	        }
393	
394	        return [$enriched, $totalGrossCents, $totalDiscountCents, $totalCommissionCents, $resolvedRate, $resolvedRateSource];
395	    }
