430	        // and stripped later by GDPR jobs; storing them here risks leakage before redaction.
431	        $safe = [
432	            'id' => Arr::get($payload, 'id'),
433	            'name' => Arr::get($payload, 'name'),
434	            'financial_status' => Arr::get($payload, 'financial_status'),
