438	            'total_discounts' => Arr::get($payload, 'total_discounts'),
439	            'total_tax' => Arr::get($payload, 'total_tax'),
440	            'currency' => Arr::get($payload, 'currency'),
441	            'created_at' => Arr::get($payload, 'created_at'),
442	            'updated_at' => Arr::get($payload, 'updated_at'),
443	        ];
444	
445	        return array_filter($safe, fn ($v) => $v !== null);
