495	    /**
496	     * Parse the `sidest_marketing_opt_in` cart attribute into explicit tri-state.
497	     * true=explicit opt-in, false=explicit opt-out, null=missing or unrecognized.
498	     *
499	     * @param  array<int, array<string, mixed>>|mixed  $noteAttributes
500	     */
501	    private function parseMarketingOptInAttribute(mixed $noteAttributes): ?bool
502	    {
503	        $raw = strtolower($this->extractCartAttribute($noteAttributes, 'sidest_marketing_opt_in'));
504	        if ($raw === '') {
505	            return null;
506	        }
507	        if (in_array($raw, ['true', '1', 'yes'], true)) {
508	            return true;
509	        }
510	        if (in_array($raw, ['false', '0', 'no'], true)) {
511	            return false;
512	        }
513	
514	        return null;
515	    }
