517	    /**
518	     * Extract a value from Shopify note_attributes (cart-level attributes).
519	     */
520	    private function extractCartAttribute(mixed $noteAttributes, string $key): string
521	    {
522	        if (! is_array($noteAttributes)) {
523	            return '';
524	        }
525	
526	        foreach ($noteAttributes as $attr) {
527	            if (is_array($attr) && strtolower(trim((string) ($attr['name'] ?? ''))) === $key) {
528	                return trim((string) ($attr['value'] ?? ''));
529	            }
530	        }
531	
532	        return '';
533	    }
