535	    /**
536	     * Resolve commission rate for a line item. Precedence:
537	     *   1. product metafield `sidest.commission_override` (brand-set per-product)
538	     *   2. brand.brand_store_settings.default_commission_rate (brand default)
539	     *   3. config('partna.store.default_commission_rate', 15) (platform fallback)
540	     *
541	     * @param  array<string, float|null>  $overrideMap
542	     * @return array{0: float, 1: string} [rate, rate_source]
543	     */
544	    private function resolveCommissionRate(
545	        string $productGid,
546	        array $overrideMap,
547	        ?BrandStoreSettings $brandSettings,
548	        float $platformDefault,
549	    ): array {
550	        if ($productGid !== '' && isset($overrideMap[$productGid]) && $overrideMap[$productGid] !== null) {
551	            $rate = (float) $overrideMap[$productGid];
552	            if ($rate > 0 && $rate <= 100) {
553	                return [$rate, 'metafield_override'];
554	            }
555	        }
556	
557	        if ($brandSettings && $brandSettings->default_commission_rate !== null) {
558	            return [(float) $brandSettings->default_commission_rate, 'brand_default'];
559	        }
560	
561	        return [$platformDefault, 'platform_default'];
562	    }
563	}
