19	// Phase 3: Handles orders/updated, orders/edited, orders/cancelled, refunds/create topics.
20	// Routes each topic to the appropriate snapshot or status-update path.
21	// commission_cents and commission_rate are FROZEN at orders/paid time (Decision #3).
22	// The trg_rollup_clawback trigger handles refund deltas in brand_affiliate_rollup automatically.
23	class ProcessShopifyOrderUpdatedWebhookJob implements ShouldQueue
24	{
25	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
26	
27	    public int $tries = 3;
28	
29	    public int $timeout = 30;
30	
31	    public function __construct(
32	        public string $professionalId,
33	        public array $payload,
34	        public string $topic,
35	        public string $shopifyEventId = '',
36	    ) {
37	        $this->onQueue('integrations');
38	    }
39	
40	    public function handle(AnalyticsCacheService $analyticsCache): void
41	    {
42	        match ($this->topic) {
43	            'orders/updated' => $this->handleUpdated($analyticsCache),
44	            'orders/edited' => $this->handleEdited($analyticsCache),
45	            'orders/cancelled' => $this->handleCancelled($analyticsCache),
46	            'refunds/create' => $this->handleRefund($analyticsCache),
47	            default => Log::warning('ProcessShopifyOrderUpdatedWebhookJob: unknown topic', [
48	                'topic' => $this->topic,
49	                'professional_id' => $this->professionalId,
50	            ]),
51	        };
52	    }
53	
54	    /**
55	     * orders/updated — LWW snapshot update. Updates gross, refund, status, and raw data.
56	     * commission_cents / commission_rate are intentionally NOT updated (frozen at paid time).
57	     */
58	    private function handleUpdated(AnalyticsCacheService $analyticsCache): void
59	    {
60	        $shopifyOrderId = (string) Arr::get($this->payload, 'id', '');
61	        $shopDomain = $this->resolveShopDomain();
62	        $shopifyUpdatedAt = Arr::get($this->payload, 'updated_at', now()->toIso8601String());
63	
64	        if ($shopifyOrderId === '' || $shopDomain === '') {
65	            return;
66	        }
67	
68	        $order = $this->findOrder($shopifyOrderId, $shopDomain);
69	        if (! $order) {
70	            // orders/updated with no existing row: stub insertion is NOT done here.
71	            // Decision: only orders/paid creates a stub-free authoritative row;
72	            // updated snapshots rely on the order existing. Skip + let reconciler fill gaps.
73	            return;
74	        }
75	
76	        $affiliateId = (string) $order->affiliate_professional_id;
77	
78	        // orders/updated: snapshot only — no event row written.
79	        // The LWW WHERE guard on shopify_updated_at makes duplicate deliveries idempotent.
80	        // 'updated' and 'snapshot' are not in the event_type CHECK constraint; only the
81	        // canonical lifecycle events (paid, edited, cancelled, refunded, etc.) are recorded.
82	        $this->snapshotUpdate($order, $shopifyUpdatedAt, 'updated');
83	
84	        $analyticsCache->invalidateAnalytics($this->professionalId);
85	        $analyticsCache->invalidateAnalytics($affiliateId);
86	    }
87	
88	    /**
89	     * orders/edited — snapshot update, commission frozen (Decision #3).
90	     * On first-seen, inserts a stub with shopify_updated_at = event_time - 1ms so
91	     * the eventual orders/paid (with later shopify_updated_at) wins LWW.
92	     * Skips if affiliate cannot be resolved from note_attributes.
93	     */
94	    private function handleEdited(AnalyticsCacheService $analyticsCache): void
95	    {
96	        $shopifyOrderId = (string) Arr::get($this->payload, 'id', '');
97	        $shopDomain = $this->resolveShopDomain();
98	        $shopifyUpdatedAt = Arr::get($this->payload, 'updated_at', now()->toIso8601String());
99	
100	        if ($shopifyOrderId === '' || $shopDomain === '') {
101	            return;
102	        }
103	
104	        $order = $this->findOrder($shopifyOrderId, $shopDomain);
105	
106	        if (! $order) {
107	            // First-seen: insert stub so event has a parent FK. If affiliate is missing, skip.
108	            $affiliateId = $this->resolveAffiliateIdFromPayload();
109	            if ($affiliateId === null) {
110	                Log::warning('ProcessShopifyOrderUpdatedWebhookJob: orders/edited first-seen, affiliate not resolvable — skipping stub', [
111	                    'shopify_order_id' => $shopifyOrderId,
112	                    'professional_id' => $this->professionalId,
113	                ]);
114	
115	                return;
116	            }
117	
118	            // stub shopify_updated_at is 1ms before event time so orders/paid wins LWW.
119	            $stubUpdatedAt = (new \Carbon\Carbon($shopifyUpdatedAt))->subMillisecond()->toIso8601String();
120	
121	            $order = $this->insertStub(
122	                shopifyOrderId: $shopifyOrderId,
123	                shopDomain: $shopDomain,
124	                affiliateProfessionalId: $affiliateId,
125	                status: 'stub',
126	                shopifyUpdatedAt: $stubUpdatedAt,
127	                occurredAt: $shopifyUpdatedAt,
128	            );
129	
130	            if (! $order) {
131	                return;
132	            }
133	        }
134	
135	        // For existing rows (non-stub): update snapshot fields only. Commission frozen.
136	        // For stub rows: the snapshot values are empty — don't overwrite with zeroes.
137	        if ($order->status !== 'stub') {
138	            $this->snapshotUpdate($order, $shopifyUpdatedAt, 'edited');
139	        }
140	
141	        $affiliateId = (string) $order->affiliate_professional_id;
142	        $this->insertEventIfNew($order->id, 'edited', $this->shopifyEventId, [], $shopifyUpdatedAt);
143	
144	        $analyticsCache->invalidateAnalytics($this->professionalId);
145	        $analyticsCache->invalidateAnalytics($affiliateId);
146	    }
147	
148	    /**
149	     * orders/cancelled — set status='cancelled'. First-seen inserts stub with status='cancelled'.
150	     * Skips if affiliate cannot be resolved.
151	     */
152	    private function handleCancelled(AnalyticsCacheService $analyticsCache): void
153	    {
154	        $shopifyOrderId = (string) Arr::get($this->payload, 'id', '');
155	        $shopDomain = $this->resolveShopDomain();
156	        $shopifyUpdatedAt = Arr::get($this->payload, 'updated_at', now()->toIso8601String());
157	
158	        if ($shopifyOrderId === '' || $shopDomain === '') {
159	            return;
160	        }
161	
162	        $order = $this->findOrder($shopifyOrderId, $shopDomain);
163	
164	        if (! $order) {
165	            $affiliateId = $this->resolveAffiliateIdFromPayload();
166	            if ($affiliateId === null) {
167	                Log::warning('ProcessShopifyOrderUpdatedWebhookJob: orders/cancelled first-seen, affiliate not resolvable — skipping stub', [
168	                    'shopify_order_id' => $shopifyOrderId,
169	                    'professional_id' => $this->professionalId,
170	                ]);
171	
172	                return;
173	            }
174	
175	            $stubUpdatedAt = (new \Carbon\Carbon($shopifyUpdatedAt))->subMillisecond()->toIso8601String();
176	            $order = $this->insertStub(
177	                shopifyOrderId: $shopifyOrderId,
178	                shopDomain: $shopDomain,
179	                affiliateProfessionalId: $affiliateId,
180	                status: 'cancelled',
181	                shopifyUpdatedAt: $stubUpdatedAt,
182	                occurredAt: $shopifyUpdatedAt,
183	            );
184	
185	            if (! $order) {
186	                return;
187	            }
188	        } else {
189	            // LWW guard: only update if the incoming timestamp is newer.
190	            // Using Eloquent update to remain database-agnostic (avoids PG-only ::cast syntax).
191	            Order::query()
192	                ->where('shopify_shop_domain', $shopDomain)
193	                ->where('shopify_order_id', $shopifyOrderId)
194	                ->where('shopify_updated_at', '<', $shopifyUpdatedAt)
195	                ->update([
196	                    'status' => 'cancelled',
197	                    'shopify_updated_at' => $shopifyUpdatedAt,
198	                    'updated_at' => now(),
199	                ]);
200	
201	            $order->refresh();
202	        }
203	
204	        $affiliateId = (string) $order->affiliate_professional_id;
205	        $this->insertEventIfNew($order->id, 'cancelled', $this->shopifyEventId, [], $shopifyUpdatedAt);
206	
207	        $analyticsCache->invalidateAnalytics($this->professionalId);
208	        $analyticsCache->invalidateAnalytics($affiliateId);
209	    }
