211	    /**
212	     * refunds/create — update refund_cents (cumulative sum of all refunds), set status.
213	     * The trg_rollup_clawback trigger fires on refund_cents change and updates brand_affiliate_rollup.
214	     * On first-seen (Race 2): insert stub with status='stub', refund_cents=<this refund>,
215	     * so the eventual orders/paid can overwrite via LWW when it arrives with a later shopify_updated_at.
216	     * Skips if affiliate cannot be resolved.
217	     */
218	    private function handleRefund(AnalyticsCacheService $analyticsCache): void
219	    {
220	        $shopifyOrderId = (string) Arr::get($this->payload, 'order_id', '');
221	        $shopDomain = $this->resolveShopDomain();
222	        $refundCreatedAt = Arr::get($this->payload, 'created_at', now()->toIso8601String());
223	
224	        // Refund payload uses order_id for the parent order reference.
225	        if ($shopifyOrderId === '' || $shopDomain === '') {
226	            return;
227	        }
228	
229	        $refundId = (string) Arr::get($this->payload, 'id', '');
230	        $refundNote = (string) Arr::get($this->payload, 'note', '');
231	
232	        // Calculate the total amount refunded in this refund object.
233	        $refundSubtotal = $this->calculateRefundSubtotal();
234	
