529	     * Calculate total gross_cents from line_items (post-discount line totals).
530	     *
531	     * @param  array<int, mixed>  $lineItems
532	     */
533	    private function calculateGrossCents(array $lineItems): int
534	    {
535	        $total = 0;
536	        foreach ($lineItems as $li) {
537	            if (! is_array($li)) {
538	                continue;
539	            }
540	            $unitPrice = (float) Arr::get($li, 'price', 0);
541	            $quantity = (int) Arr::get($li, 'quantity', 1);
542	            $discount = (float) Arr::get($li, 'total_discount', 0);
543	            $lineCents = (int) round($unitPrice * $quantity * 100) - (int) round($discount * 100);
544	            $total += max(0, $lineCents);
545	        }
546	
547	        return $total;
548	    }
