579	            return 0;
580	        }
581	        foreach ($refunds as $refund) {
582	            if (! is_array($refund)) {
583	                continue;
584	            }
585	            $refundLines = Arr::get($refund, 'refund_line_items', []);
586	            if (! is_array($refundLines)) {
